/**
 * M4b repository code search acceptance suite (REQ-4-2-3).
 *
 * Seed data (docs/seed-data.md): on acme-docs' default branch `main`, the known
 * query `search flow` matches `README.md` and `src/search.ts` (whitespace-token OR,
 * case-insensitive substring), `docs/overview.md` does not match, and the private
 * `secret-research` repository also contains the term `research` — so it is the
 * cross-repository leak witness.
 *
 * The suite is read-only: it never creates a commit or changes a file.
 */
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';
import { repo as repoCopy, shell as shellCopy } from '../frontend/src/contracts/copy';

const OWNER = 'alice-dev';
const REPO = 'acme-docs';
const BASE = `/${OWNER}/${REPO}`;

function searchBox(page: Page) {
  return page.getByRole('searchbox', { name: shellCopy.search });
}

async function searchFromRepository(page: Page, query: string) {
  await page.goto(BASE);
  await expect(page.getByRole('searchbox', { name: shellCopy.search })).toHaveCount(1);
  await searchBox(page).fill(query);
  await searchBox(page).press('Enter');
}

test.describe('REQ-4-2-3 search code within a repository', () => {
  test('the repository search box opens Code results that filter by path', async ({ page }) => {
    await searchFromRepository(page, 'search flow');
    await expect(page).toHaveURL(/\/search\?q=search%20flow&repo=alice-dev%2Facme-docs$/);

    // Exactly one results-type link named exactly "Code" (no repository nav here).
    await expect(page.getByRole('link', { name: repoCopy.code, exact: true })).toHaveCount(1);
    await page.getByRole('link', { name: repoCopy.code, exact: true }).click();

    // Both default-branch matches, each result link named exactly after the file.
    const readme = page.getByRole('link', { name: 'README.md', exact: true });
    const source = page.getByRole('link', { name: 'search.ts', exact: true });
    await expect(readme).toBeVisible();
    await expect(source).toBeVisible();
    await expect(page.getByText('src/search.ts', { exact: true })).toBeVisible();
    await expect(page.getByTestId('code-result-branch').first()).toHaveText('main');
    await expect(page.getByTestId('code-results').locator('pre code').first()).toContainText('search flow');

    // The optional path filter limits the results to src/.
    await page.getByLabel(repoCopy.pathFilter, { exact: true }).fill('src/');
    await expect(source).toBeVisible();
    await expect(readme).toHaveCount(0);

    // Clicking a result opens the file near the match (the file page shows the source).
    await source.click();
    await expect(page).toHaveURL(new RegExp(`${BASE}/blob/main/src/search.ts$`));
    await expect(page.locator('pre code')).toContainText('searchRepositories');

    // Clearing the filter shows the other match again, and nothing from the private
    // repository ever leaks into the results.
    await page.goBack();
    await page.getByLabel(repoCopy.pathFilter, { exact: true }).fill('');
    await expect(readme).toBeVisible();
    await expect(page.getByText('secret-research')).toHaveCount(0);
  });

  test('the optional language filter keeps only that language', async ({ page }) => {
    await searchFromRepository(page, 'search flow');
    await page.getByLabel(repoCopy.languageFilter, { exact: true }).selectOption('markdown');
    await expect(page.getByRole('link', { name: 'README.md', exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: 'search.ts', exact: true })).toHaveCount(0);

    await page.getByLabel(repoCopy.languageFilter, { exact: true }).selectOption('typescript');
    await expect(page.getByRole('link', { name: 'search.ts', exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: 'README.md', exact: true })).toHaveCount(0);
  });

  test('an absent query shows No code results and the exact query survives a reload', async ({ page }) => {
    await searchFromRepository(page, 'no-such-token');

    const empty = page.getByTestId('no-code-results');
    await expect(empty).toBeVisible();
    await expect(empty).toHaveText(repoCopy.noCodeResults);
    await expect(page.getByTestId('code-results')).toHaveCount(0);
    await expect(searchBox(page)).toHaveValue('no-such-token');

    await page.reload();
    await expect(searchBox(page)).toHaveValue('no-such-token');
    await expect(page.getByTestId('no-code-results')).toBeVisible();
    await expect(page.getByTestId('code-results')).toHaveCount(0);

    // Repeating the same search from the repository page reproduces the empty state.
    await searchFromRepository(page, 'no-such-token');
    await expect(page.getByTestId('no-code-results')).toBeVisible();
    await expect(page.getByTestId('code-results')).toHaveCount(0);
  });

  test('the search stays inside the current repository and writes nothing', async ({ page }) => {
    const before = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=main`)).json();

    // `research` exists only in the private secret-research repository.
    await searchFromRepository(page, 'research');
    await expect(page.getByTestId('no-code-results')).toBeVisible();
    await expect(page.getByText('secret-research')).toHaveCount(0);

    // The default-branch scope shows the revision context of the current repository.
    await searchFromRepository(page, 'search flow');
    await expect(page.getByTestId('code-result-branch').first()).toHaveText('main');
    await expect(page.getByTestId('code-results').locator('li')).toHaveCount(2);

    const after = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=main`)).json();
    expect(after.count).toBe(before.count);
    expect(after.commits[0].message).toBe(before.commits[0].message);
  });
});

########## code-branches ##########
/**
 * M4b branch selector acceptance suite (REQ-4-3-1 / REQ-4-3-2, plus the REQ-4-1
 * THEN2 regression).
 *
 * Every test starts from a fresh browser context and uses the real seed data
 * (docs/seed-data.md): acme-docs with branches main / feature-search / release and
 * the branch-only file main-only.md.
 *
 * Shared-DB discipline: branch writes only add new `pw-branch-*` branches that
 * point at the current head; acme-docs' main head is never moved, so the
 * diffstat assertions of content.spec.ts stay valid.
 */
import { expect, test } from '@playwright/test';
import { errors as errorCopy, moduleCopy, repo as repoCopy } from '../frontend/src/contracts/copy';
import {
  SEED_ACCOUNT,
  TIER_ACCOUNTS,
  branchTrigger,
  createBranchViaUi,
  selectBranch,
  signIn,
  uniqueToken,
} from './helpers';

const OWNER = 'alice-dev';
const REPO = 'acme-docs';
const BASE = `/${OWNER}/${REPO}`;

test.describe('REQ-4-3-1 list and switch repository branches', () => {
  test('the unique selector lists branches, marks the current one and switches page and file list', async ({ page }) => {
    await page.goto(BASE);
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption('main'));

    await branchTrigger(page).click();
    await expect(page.getByRole('textbox', { name: moduleCopy.findBranch })).toBeVisible();
    await expect(page.getByRole('option', { name: 'main', exact: true })).toHaveAttribute('aria-selected', 'true');
    // The default branch carries a screen-reader-hidden badge.
    await expect(page.getByRole('option', { name: 'main', exact: true })).toContainText('default');

    await page.getByRole('textbox', { name: moduleCopy.findBranch }).fill('feature-search');
    await expect(page.getByRole('option', { name: 'main', exact: true })).toHaveCount(0);
    await page.getByRole('option', { name: 'feature-search', exact: true }).click();

    await expect(page).toHaveURL(new RegExp(`${BASE}/tree/feature-search$`));
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption('feature-search'));
    await expect(page.getByRole('link', { name: 'main-only.md', exact: true })).toBeVisible();

    await selectBranch(page, 'main');
    await expect(page).toHaveURL(new RegExp(`${BASE}/tree/main$`));
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption('main'));
    await expect(page.getByRole('link', { name: 'main-only.md', exact: true })).toHaveCount(0);
  });

  test('an unmatched query shows the empty state, Escape closes it and the branch survives a reload', async ({ page }) => {
    await page.goto(`${BASE}/blob/main/README.md`);

    await branchTrigger(page).click();
    await page.getByRole('textbox', { name: moduleCopy.findBranch }).fill('no-such-branch-xyz');
    await expect(page.getByText(repoCopy.noMatchingBranch)).toBeVisible();

    await page.keyboard.press('Escape');
    await expect(page.getByRole('textbox', { name: moduleCopy.findBranch })).toHaveCount(0);
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption('main'));
    await expect(page).toHaveURL(new RegExp(`${BASE}/blob/main/README.md$`));

    await page.reload();
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption('main'));
    await expect(page).toHaveURL(new RegExp(`${BASE}/blob/main/README.md$`));
  });

  test('switching from feature-search to main hides the branch-only file (REQ-4-1 THEN2)', async ({ page }) => {
    await page.goto(`${BASE}/blob/feature-search/main-only.md`);
    await expect(page.getByText('Notes kept on the feature-search branch.')).toBeVisible();

    await selectBranch(page, 'main');
    await expect(page).toHaveURL(new RegExp(`${BASE}/blob/main/main-only.md$`));
    await expect(page.getByText('Notes kept on the feature-search branch.')).toHaveCount(0);
    await expect(page.getByText(repoCopy.pathNotFound)).toBeVisible();

    await page.reload();
    await expect(page).toHaveURL(new RegExp(`${BASE}/blob/main/main-only.md$`));
    await expect(page.getByText(repoCopy.pathNotFound)).toBeVisible();
  });
});

test.describe('REQ-4-3-2 create a branch from an existing revision', () => {
  test('a Write collaborator creates the branch at the current head and it stays selected after a reload', async ({
    page,
  }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await page.goto(BASE);
    const branch = uniqueToken('pw-branch');

    await createBranchViaUi(page, branch);
    await expect(page).toHaveURL(new RegExp(`${BASE}/tree/${branch}$`));
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption(branch));

    // The new branch points at the head of the branch it was created from and
    // records its creator; the original branch history is not rewritten.
    const list = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/branches`)).json();
    const created = list.branches.find((entry: { name: string }) => entry.name === branch);
    const main = list.branches.find((entry: { name: string }) => entry.name === 'main');
    expect(created.headCommitId).toBe(main.headCommitId);
    expect(created.isDefault).toBe(false);
    expect(created.createdBy).toBe('alice-dev');

    const history = await (
      await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=${branch}`)
    ).json();
    expect(history.count).toBe(2);
    expect(history.commits[0].message).toBe('Document search flow');

    await page.reload();
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption(branch));
  });

  test('an invalid name immediately shows Invalid branch and creates no reference', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await page.goto(BASE);

    await branchTrigger(page).click();
    await page.getByRole('textbox', { name: moduleCopy.findBranch }).fill('invalid..branch');
    await expect(page.getByText(errorCopy.invalidBranch)).toBeVisible();
    await expect(
      page.getByRole('option', { name: moduleCopy.createBranch('invalid..branch'), exact: true }),
    ).toHaveCount(0);

    const list = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/branches`)).json();
    expect(list.branches.some((entry: { name: string }) => entry.name === 'invalid..branch')).toBe(false);
  });

  test('Read, Triage and anonymous viewers get no creation entry and the API rejects them', async ({ page, request }) => {
    const readName = uniqueToken('read-branch');
    const triageName = uniqueToken('triage-branch');

    // Visitor: no creation entry, and the API requires authentication.
    await page.goto(BASE);
    await branchTrigger(page).click();
    await page.getByRole('textbox', { name: moduleCopy.findBranch }).fill(readName);
    await expect(page.getByRole('option', { name: moduleCopy.createBranch(readName), exact: true })).toHaveCount(0);
    await page.keyboard.press('Escape');
    expect((await request.post(`/api/repos/${OWNER}/${REPO}/branches`, { data: { name: readName } })).status()).toBe(
      401,
    );

    // Triage: no creation entry, API answered with 403.
    await signIn(page, TIER_ACCOUNTS.triage.username, TIER_ACCOUNTS.triage.password);
    await page.goto(BASE);
    await branchTrigger(page).click();
    await page.getByRole('textbox', { name: moduleCopy.findBranch }).fill(triageName);
    await expect(page.getByRole('option', { name: moduleCopy.createBranch(triageName), exact: true })).toHaveCount(0);
    await page.keyboard.press('Escape');
    expect(
      (await page.request.post(`/api/repos/${OWNER}/${REPO}/branches`, { data: { name: triageName } })).status(),
    ).toBe(403);

    // Read: the same, with a third distinct name.
    const readTierName = uniqueToken('read-tier');
    await signIn(page, 'dave-reader', SEED_ACCOUNT.password);
    await page.goto(BASE);
    await branchTrigger(page).click();
    await page.getByRole('textbox', { name: moduleCopy.findBranch }).fill(readTierName);
    await expect(page.getByRole('option', { name: moduleCopy.createBranch(readTierName), exact: true })).toHaveCount(0);
    await page.keyboard.press('Escape');
    expect(
      (await page.request.post(`/api/repos/${OWNER}/${REPO}/branches`, { data: { name: readTierName } })).status(),
    ).toBe(403);

    const list = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/branches`)).json();
    const names = list.branches.map((entry: { name: string }) => entry.name);
    expect(names).not.toContain(readName);
    expect(names).not.toContain(triageName);
    expect(names).not.toContain(readTierName);
  });
});
