########## code-editor ##########
/**
 * M4b web file editor acceptance suite (REQ-4-4).
 *
 * Shared-DB discipline: every file and branch write happens on a throwaway
 * `pw-branch-*` branch created through the selector, so acme-docs' `main` head is
 * never advanced (content.spec.ts asserts its diffstat and last-commit shape).
 * Rejected submissions are asserted to leave file, branch head and history intact.
 */
import { expect, test } from '@playwright/test';
import { content as contentCopy, errors as errorCopy, moduleCopy, repo as repoCopy } from '../frontend/src/contracts/copy';
import { SEED_ACCOUNT, TIER_ACCOUNTS, branchTrigger, createBranchViaUi, signIn, uniqueToken } from './helpers';

const OWNER = 'alice-dev';
const REPO = 'acme-docs';
const BASE = `/${OWNER}/${REPO}`;
const PROTECTED = '/alice-dev/protected-sandbox';

/** Create a scratch branch and land on its directory page. */
async function scratchBranch(page: import('@playwright/test').Page) {
  const branch = uniqueToken('pw-branch');
  await createBranchViaUi(page, branch);
  await expect(page).toHaveURL(new RegExp(`${BASE}/tree/${branch}$`));
  return branch;
}

async function openNewFileEditor(page: import('@playwright/test').Page) {
  await page.getByRole('button', { name: repoCopy.addFile, exact: true }).click();
  await page.getByRole('menuitem', { name: repoCopy.createNewFile, exact: true }).click();
}

test.describe('REQ-4-4 manage repository files through the web interface', () => {
  test('a Write collaborator creates a file in one commit that the history shows', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await page.goto(BASE);
    const branch = await scratchBranch(page);

    const fileName = `${uniqueToken('pw-file').slice(0, 24)}.md`;
    const content = '# hello\n\nweb edited content\n';

    await openNewFileEditor(page);
    await expect(page).toHaveURL(new RegExp(`${BASE}/new/${branch}$`));
    await page.getByLabel(repoCopy.fileName, { exact: true }).fill(`docs/${fileName}`);
    await page.getByRole('textbox', { name: repoCopy.fileContents, exact: true }).fill(content);
    await page.getByLabel(repoCopy.commitMessage, { exact: true }).fill(`Add ${fileName}`);
    await page.getByRole('button', { name: repoCopy.commitChanges, exact: true }).click();

    // The exact saved content is displayed immediately.
    await expect(page).toHaveURL(new RegExp(`${BASE}/blob/${branch}/docs/${fileName}$`));
    await expect(page.locator('pre code')).toHaveText(content);

    // Exactly one commit, its parent is the original branch head, and the branch moved.
    const history = await (
      await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=${branch}`)
    ).json();
    expect(history.count).toBe(3);
    expect(history.commits[0].message).toBe(`Add ${fileName}`);
    expect(history.commits[0].changedFiles).toEqual([
      { path: `docs/${fileName}`, status: 'added', additions: 3, deletions: 0 },
    ]);
    expect(history.commits[1].message).toBe('Document search flow');
    expect(history.commits[0].parentId).toBe(history.commits[1].id);

    // The "Commits" history of the file shows the exact submitted message.
    await page.getByRole('link', { name: contentCopy.commits, exact: true }).click();
    await expect(page).toHaveURL(new RegExp(`${BASE}/commits/${branch}/docs/${fileName}$`));
    await expect(page.getByText(`Add ${fileName}`, { exact: true })).toBeVisible();

    // Refresh persistence.
    await page.goto(`${BASE}/blob/${branch}/docs/${fileName}`);
    await expect(page.locator('pre code')).toHaveText(content);
  });

  test('an invalid path and a blank message report the exact copy and change nothing', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await page.goto(BASE);
    const branch = await scratchBranch(page);
    const before = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=${branch}`)).json();

    await openNewFileEditor(page);
    await page.getByLabel(repoCopy.fileName, { exact: true }).fill('../invalid.md');
    await page.getByRole('textbox', { name: repoCopy.fileContents, exact: true }).fill('must not be saved');
    await page.getByRole('button', { name: repoCopy.commitChanges, exact: true }).click();

    await expect(page.getByText(errorCopy.invalidFilePath)).toBeVisible();
    await expect(page.getByText(errorCopy.commitMessageRequired)).toBeVisible();

    const after = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=${branch}`)).json();
    expect(after.count).toBe(before.count);
    expect(after.commits[0].message).toBe(before.commits[0].message);
    const lookup = await page.request.get(
      `/api/repos/${OWNER}/${REPO}/contents?branch=${branch}&path=${encodeURIComponent('../invalid.md')}`,
    );
    expect(lookup.status()).toBe(404);
  });

  test('a path that conflicts with an existing file is rejected with zero changes', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await page.goto(BASE);
    const branch = await scratchBranch(page);
    const before = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=${branch}`)).json();

    await openNewFileEditor(page);
    await page.getByLabel(repoCopy.fileName, { exact: true }).fill('README.md');
    await page.getByRole('textbox', { name: repoCopy.fileContents, exact: true }).fill('overwritten');
    await page.getByLabel(repoCopy.commitMessage, { exact: true }).fill('Conflict');
    await page.getByRole('button', { name: repoCopy.commitChanges, exact: true }).click();

    await expect(page.getByText(errorCopy.invalidFilePath)).toBeVisible();

    const after = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=${branch}`)).json();
    expect(after.count).toBe(before.count);
    // The existing README of the branch is byte-identical to main's README.
    const mainReadme = await (
      await page.request.get(`/api/repos/${OWNER}/${REPO}/contents?branch=main&path=README.md`)
    ).json();
    const branchReadme = await (
      await page.request.get(`/api/repos/${OWNER}/${REPO}/contents?branch=${branch}&path=README.md`)
    ).json();
    expect(branchReadme.contents.content).toBe(mainReadme.contents.content);
    expect(branchReadme.contents.content).not.toBe('overwritten');
  });

  test('a protected branch refuses the write with its own message and zero changes', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    await page.goto(PROTECTED);
    await expect(branchTrigger(page)).toHaveAccessibleName(moduleCopy.branchOption('main'));
    const before = await (
      await page.request.get('/api/repos/alice-dev/protected-sandbox/commits?branch=main')
    ).json();

    await openNewFileEditor(page);
    await page.getByLabel(repoCopy.fileName, { exact: true }).fill('blocked.md');
    await page.getByRole('textbox', { name: repoCopy.fileContents, exact: true }).fill('must not be saved');
    await page.getByLabel(repoCopy.commitMessage, { exact: true }).fill('Blocked write');
    await page.getByRole('button', { name: repoCopy.commitChanges, exact: true }).click();

    await expect(page.getByText(errorCopy.branchProtected)).toBeVisible();

    const after = await (
      await page.request.get('/api/repos/alice-dev/protected-sandbox/commits?branch=main')
    ).json();
    expect(after.count).toBe(before.count);
    expect(after.commits[0].message).toBe(before.commits[0].message);
  });

  test('Read, Triage and anonymous viewers see no Add file control and the API rejects them', async ({
    page,
    request,
  }) => {
    const payload = { branch: 'main', path: 'must-not-exist.md', content: 'x', message: 'Add file' };

    // Visitor: no Add file button, API requires authentication.
    await page.goto(BASE);
    await expect(page.getByRole('button', { name: repoCopy.addFile, exact: true })).toHaveCount(0);
    expect((await request.post(`/api/repos/${OWNER}/${REPO}/contents`, { data: payload })).status()).toBe(401);

    // Read tier.
    await signIn(page, 'dave-reader', SEED_ACCOUNT.password);
    await page.goto(BASE);
    await expect(page.getByRole('button', { name: repoCopy.addFile, exact: true })).toHaveCount(0);
    expect((await page.request.post(`/api/repos/${OWNER}/${REPO}/contents`, { data: payload })).status()).toBe(403);

    // Triage tier.
    await signIn(page, TIER_ACCOUNTS.triage.username, TIER_ACCOUNTS.triage.password);
    await page.goto(BASE);
    await expect(page.getByRole('button', { name: repoCopy.addFile, exact: true })).toHaveCount(0);
    expect((await page.request.post(`/api/repos/${OWNER}/${REPO}/contents`, { data: payload })).status()).toBe(403);

    // Nothing was written to main.
    const main = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=main`)).json();
    expect(main.count).toBe(2);
    expect(main.commits[0].message).toBe('Document search flow');
  });
});
