/**
 * M4b default-branch settings acceptance suite (REQ-4-3-3).
 *
 * Shared-DB discipline: the admin case changes the default branch to `release` and
 * then changes it back to `main` through the same UI inside a `finally` block, so
 * the rest of the suite (content.spec.ts asserts `Branch main`) starts from the
 * seeded default branch again.
 */
import { expect, test } from '@playwright/test';
import { repo as repoCopy } from '../frontend/src/contracts/copy';
import { SEED_ACCOUNT, TIER_ACCOUNTS, branchTrigger, signIn } from './helpers';

const OWNER = 'alice-dev';
const REPO = 'acme-docs';
const BASE = `/${OWNER}/${REPO}`;
const SETTINGS = `${BASE}/settings/branches`;

test.describe('REQ-4-3-3 change the repository default branch', () => {
  test('an Admin moves the default branch and the old branch stays selectable', async ({ page }) => {
    await signIn(page, SEED_ACCOUNT.username, SEED_ACCOUNT.password);
    try {
      await page.goto(SETTINGS);
      // "Branches" is a unique link on its settings page.
      await expect(page.getByRole('link', { name: repoCopy.branches, exact: true })).toHaveCount(1);

      const select = page.getByRole('combobox', { name: repoCopy.defaultBranch, exact: true });
      await expect(select).toBeVisible();
      await expect(select).toHaveValue('main');

      await select.selectOption('release');
      await page.getByRole('button', { name: repoCopy.update, exact: true }).click();
      await page.getByRole('button', { name: repoCopy.confirm, exact: true }).click();

      // Refreshing the settings page keeps `release`.
      await page.goto(SETTINGS);
      await expect(page.getByRole('combobox', { name: repoCopy.defaultBranch, exact: true })).toHaveValue('release');

      // Opening the repository entry point without a branch shows the new default.
      await page.goto(BASE);
      await expect(branchTrigger(page)).toHaveAccessibleName(`Branch release`);

      // The previous default branch is still offered and still has its history.
      await branchTrigger(page).click();
      await expect(page.getByRole('option', { name: 'main', exact: true })).toBeVisible();
      await page.keyboard.press('Escape');
      const main = await (await page.request.get(`/api/repos/${OWNER}/${REPO}/commits?branch=main`)).json();
      expect(main.commits[0].message).toBe('Document search flow');
    } finally {
      // Roll the shared database back to the seeded default branch through the UI.
      await page.goto(SETTINGS);
      await page.getByRole('combobox', { name: repoCopy.defaultBranch, exact: true }).selectOption('main');
      await page.getByRole('button', { name: repoCopy.update, exact: true }).click();
      await page.getByRole('button', { name: repoCopy.confirm, exact: true }).click();
      await page.goto(BASE);
      await expect(branchTrigger(page)).toHaveAccessibleName('Branch main');
    }
  });

  test('a non-Admin gets no Default branch combobox and no update button, and the API rejects the change', async ({
    page,
  }) => {
    // Visitor: the Settings navigation is not even offered.
    await page.goto(BASE);
    await expect(page.getByRole('link', { name: repoCopy.settings, exact: true })).toHaveCount(0);
    await page.goto(SETTINGS);
    await expect(page.getByRole('combobox', { name: repoCopy.defaultBranch, exact: true })).toHaveCount(0);
    await expect(page.getByRole('button', { name: repoCopy.update, exact: true })).toHaveCount(0);

    // Maintain (Write-and-above, still not an Admin): same absence, API 403.
    await signIn(page, TIER_ACCOUNTS.maintain.username, TIER_ACCOUNTS.maintain.password);
    await page.goto(SETTINGS);
    await expect(page.getByRole('combobox', { name: repoCopy.defaultBranch, exact: true })).toHaveCount(0);
    await expect(page.getByRole('button', { name: repoCopy.update, exact: true })).toHaveCount(0);
    expect(
      (await page.request.put(`/api/repos/${OWNER}/${REPO}/default-branch`, { data: { branch: 'release' } })).status(),
    ).toBe(403);

    // The saved default branch is unchanged.
    const repository = await (await page.request.get(`/api/repos/${OWNER}/${REPO}`)).json();
    expect(repository.repository.defaultBranch).toBe('main');
  });
});

