/**
 * Repository seed data (docs/seed-data.md — M3 share: repositories, files,
 * branches and commits).
 *
 * Everything is keyed by business identity and written with insert-if-absent, so
 * running the seed again (every application start) never overwrites data a user
 * produced: an advanced branch keeps its head, an edited README keeps its
 * content, a changed password keeps its hash.
 *
 * Repositories must be created *after* the account seed; `seed/all.js` imports
 * this module after `accounts.js`, and the registry preserves that order.
 */
import { registerSeed } from './index.js';

/** Public demo repository (REQ-3-1/3-3 read scenarios). */
export const SEED_PUBLIC_REPO = { owner: 'alice-dev', name: 'acme-docs' };
/** Private repository a visitor must never see (REQ-3-1/3-3/3-4). */
export const SEED_PRIVATE_REPO = { owner: 'alice-dev', name: 'secret-research' };
/** Existing fork name in the personal namespace (REQ-3-2-2 conflict case). */
export const SEED_FORK_CONFLICT_REPO = { owner: 'alice-dev', name: 'acme-docs-fork' };
/** Acme Demo organisation repositories (one public, one private). */
export const SEED_ORG = { name: 'acme-demo', displayName: 'Acme Demo' };
export const SEED_ORG_REPOS = {
  public: { owner: 'acme-demo', name: 'org-handbook' },
  private: { owner: 'acme-demo', name: 'org-private' },
};

const ACME_DOCS_TREES = {
  base: {
    'README.md': '# acme-docs\n\nRepository documentation for the Acme demo project.\n',
    'src/search.ts': 'export function searchRepositories(query: string): string[] {\n  return [];\n}\n',
    'docs/guide.md': '# Guide\n\nHow to browse the acme-docs repository.\n',
  },
  searching: {
    'README.md': '# acme-docs\n\nThis repository documents the **search flow** of the platform.\n',
    'src/search.ts': 'export function searchRepositories(query: string): string[] {\n  return query ? [query] : [];\n}\n',
    'docs/guide.md': '# Guide\n\nHow to browse the acme-docs repository.\n',
  },
};

function userByUsername(db, username) {
  const row = db.prepare('SELECT * FROM users WHERE username = ?').get(username);
  if (!row) throw new Error(`seed(repos): account "${username}" must exist before the repository seed runs`);
  return row;
}

function ensureOrganisation(db, name, displayName) {
  db.prepare('INSERT INTO organizations (name, display_name) VALUES (?, ?) ON CONFLICT DO NOTHING').run(
    name,
    displayName,
  );
  return db.prepare('SELECT * FROM organizations WHERE name = ?').get(name);
}

function ensureOrgMember(db, orgId, userId, role) {
  db.prepare('INSERT OR IGNORE INTO org_members (org_id, user_id, role) VALUES (?, ?, ?)').run(orgId, userId, role);
}

/** Insert-if-absent by business key; returns the (possibly pre-existing) row. */
function ensureRepository(db, { ownerUserId = null, ownerOrgId = null, name, description = '', visibility, forkSourceId = null }) {
  const existing =
    ownerUserId != null
      ? db.prepare('SELECT * FROM repos WHERE owner_user_id = ? AND name = ?').get(ownerUserId, name)
      : db.prepare('SELECT * FROM repos WHERE owner_org_id = ? AND name = ?').get(ownerOrgId, name);
  if (existing) return existing;
  return db
    .prepare(
      `INSERT INTO repos (owner_user_id, owner_org_id, name, description, visibility, fork_source_id)
       VALUES (?, ?, ?, ?, ?, ?) RETURNING *`,
    )
    .get(ownerUserId, ownerOrgId, name, description, visibility, forkSourceId);
}

/** Commits are keyed by (repository, message) so re-seeding is idempotent. */
function ensureCommit(db, { repoId, authorId, message, tree, parentId = null, files = [] }) {
  const existing = db.prepare('SELECT * FROM commits WHERE repo_id = ? AND message = ?').get(repoId, message);
  if (existing) return existing;
  const commit = db
    .prepare(
      `INSERT INTO commits (repo_id, parent_id, author_id, message, tree_json)
       VALUES (?, ?, ?, ?, ?) RETURNING *`,
    )
    .get(repoId, parentId, authorId, message, JSON.stringify(tree));
  const insertFile = db.prepare(
    'INSERT INTO commit_files (commit_id, path, status, additions, deletions) VALUES (?, ?, ?, ?, ?)',
  );
  for (const file of files) insertFile.run(commit.id, file.path, file.status, file.additions ?? 0, file.deletions ?? 0);
  return commit;
}

function ensureBranch(db, { repoId, name, headCommitId }) {
  const existing = db.prepare('SELECT * FROM branches WHERE repo_id = ? AND name = ?').get(repoId, name);
  if (existing) return existing;
  return db
    .prepare('INSERT INTO branches (repo_id, name, head_commit_id) VALUES (?, ?, ?) RETURNING *')
    .get(repoId, name, headCommitId);
}

/** Only fills a missing pointer: a default branch a user changed stays changed. */
function ensureDefaultBranch(db, repo, branch) {
  if (repo.default_branch_id != null) return;
  db.prepare('UPDATE repos SET default_branch_id = ? WHERE id = ? AND default_branch_id IS NULL').run(
    branch.id,
    repo.id,
  );
}

function ensureGrant(db, repoId, userId, role) {
  db.prepare('INSERT OR IGNORE INTO repo_grants (repo_id, subject_user_id, role) VALUES (?, ?, ?)').run(
    repoId,
    userId,
    role,
  );
}

/** Repository + default branch + one initial commit with the given files. */
function seedSimpleRepository(db, { ownerUserId, ownerOrgId, name, description, visibility, authorId, message, tree }) {
  const repo = ensureRepository(db, { ownerUserId, ownerOrgId, name, description, visibility });
  const commit = ensureCommit(db, {
    repoId: repo.id,
    authorId,
    message,
    tree,
    files: Object.keys(tree).map((path) => ({ path, status: 'added', additions: 1, deletions: 0 })),
  });
  const branch = ensureBranch(db, { repoId: repo.id, name: 'main', headCommitId: commit.id });
  ensureDefaultBranch(db, repo, branch);
  return repo;
}

function seedAcmeDocs(db, alice) {
  const repo = ensureRepository(db, {
    ownerUserId: alice.id,
    name: SEED_PUBLIC_REPO.name,
    description: 'Documentation for the Acme demo project',
    visibility: 'public',
  });

  const initial = ensureCommit(db, {
    repoId: repo.id,
    authorId: alice.id,
    message: 'Initial commit',
    tree: ACME_DOCS_TREES.base,
    files: [
      { path: 'README.md', status: 'added', additions: 2, deletions: 0 },
      { path: 'src/search.ts', status: 'added', additions: 2, deletions: 0 },
      { path: 'docs/guide.md', status: 'added', additions: 2, deletions: 0 },
    ],
  });

  const searchFlow = ensureCommit(db, {
    repoId: repo.id,
    authorId: alice.id,
    message: 'Document search flow',
    tree: ACME_DOCS_TREES.searching,
    parentId: initial.id,
    files: [
      { path: 'src/search.ts', status: 'modified', additions: 1, deletions: 1 },
      { path: 'README.md', status: 'modified', additions: 1, deletions: 1 },
    ],
  });

  const main = ensureBranch(db, { repoId: repo.id, name: 'main', headCommitId: searchFlow.id });
  ensureDefaultBranch(db, repo, main);

  // feature-search is ahead of main by at least one commit and carries main-only.md.
  const featureTree = {
    ...ACME_DOCS_TREES.searching,
    'README.md': `${ACME_DOCS_TREES.searching['README.md']}\nThe branch also keeps notes.\n`,
    'main-only.md': '# main-only\n\nNotes kept on the feature-search branch.\n',
  };
  const featureCommit = ensureCommit(db, {
    repoId: repo.id,
    authorId: alice.id,
    message: 'Add main-only notes',
    tree: featureTree,
    parentId: searchFlow.id,
    files: [
      { path: 'main-only.md', status: 'added', additions: 2, deletions: 0 },
      { path: 'README.md', status: 'modified', additions: 1, deletions: 0 },
    ],
  });
  ensureBranch(db, { repoId: repo.id, name: 'feature-search', headCommitId: featureCommit.id });

  return repo;
}

/** @param {import('better-sqlite3').Database} db */
export function seedRepositories(db) {
  const alice = userByUsername(db, 'alice-dev');
  const bob = userByUsername(db, 'bob-reviewer');

  // M3 owns the repository share of the organisation seed; M2 layers the rest
  // (teams, member governance) on top, both idempotent.
  const org = ensureOrganisation(db, SEED_ORG.name, SEED_ORG.displayName);
  ensureOrgMember(db, org.id, alice.id, 'owner');
  ensureOrgMember(db, org.id, bob.id, 'member');

  const acmeDocs = seedAcmeDocs(db, alice);

  // Private repository: the visitor must not find it in search or open it.
  const secretResearch = seedSimpleRepository(db, {
    ownerUserId: alice.id,
    name: SEED_PRIVATE_REPO.name,
    description: 'Private research notes ready for public display',
    visibility: 'private',
    authorId: alice.id,
    message: 'Add research notes',
    tree: {
      'README.md': '# secret-research\n\nPrivate research notes that are ready for public display.\n',
      'docs/notes.md': '# Notes\n\nCollected research notes.\n',
    },
  });

  // Existing repository name used by the fork conflict scenario (REQ-3-2-2).
  seedSimpleRepository(db, {
    ownerUserId: alice.id,
    name: SEED_FORK_CONFLICT_REPO.name,
    description: 'Fork sandbox used by the fork conflict scenario',
    visibility: 'public',
    authorId: alice.id,
    message: 'Initial commit',
    tree: { 'README.md': '# acme-docs-fork\n\nFork sandbox repository.\n' },
  });

  seedSimpleRepository(db, {
    ownerOrgId: org.id,
    name: SEED_ORG_REPOS.public.name,
    description: 'Public handbook of the Acme Demo organisation',
    visibility: 'public',
    authorId: alice.id,
    message: 'Add handbook',
    tree: { 'README.md': '# org-handbook\n\nHandbook for the Acme Demo organisation.\n' },
  });

  seedSimpleRepository(db, {
    ownerOrgId: org.id,
    name: SEED_ORG_REPOS.private.name,
    description: 'Private notes of the Acme Demo organisation',
    visibility: 'private',
    authorId: alice.id,
    message: 'Add private notes',
    tree: { 'README.md': '# org-private\n\nPrivate organisation notes.\n' },
  });

  // REQ-3-4 needs a distinct non-Admin collaborator on a private repository:
  // bob-reviewer may view secret-research and reach its settings, but is not an
  // Admin, so the visibility action stays hidden and the API rejects it.
  ensureGrant(db, acmeDocs.id, bob.id, 'write');
  ensureGrant(db, secretResearch.id, bob.id, 'write');
}

registerSeed('repos', seedRepositories);

