import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { FileText, Folder, GitBranch } from 'lucide-react';
import { repo as repoCopy } from '../../contracts/copy';
import { repoApi } from './api';
import type { RepositoryContents } from './api';
import { RepoHeader, RepoNav } from './RepoHeader';
import { RepositoryMissing } from './RepositoryMissing';
import { useRepository } from './useRepository';

/**
 * Read-only content pages of a repository (`/blob/...` for a file, `/tree/...` for
 * a directory).
 *
 * REQ-3-3 requires that a visitor can click a file name in the overview and enter
 * the file-content page, so this module ships the read path it needs on the route
 * convention published for the code-browsing module (REQ-4): the Code page,
 * commit history, diffs, branch selector and file editing stay with REQ-4.
 */
export function RepositoryContentsPage({ kind }: { kind: 'file' | 'directory' }) {
  const params = useParams();
  const owner = params.owner ?? '';
  const name = params.repo ?? '';
  const branch = params.branch ?? '';
  const path = (params['*'] ?? '').replace(/^\/+|\/+$/g, '');
  const repoState = useRepository(owner, name);
  const [state, setState] = useState<{ status: 'loading' } | { status: 'ready'; contents: RepositoryContents } | { status: 'missing' }>({
    status: 'loading',
  });

  useEffect(() => {
    if (repoState.status !== 'ready') return;
    let active = true;
    setState({ status: 'loading' });
    repoApi
      .contents(owner, name, branch, path)
      .then((contents) => {
        if (active) setState({ status: 'ready', contents });
      })
      .catch(() => {
        if (active) setState({ status: 'missing' });
      });
    return () => {
      active = false;
    };
  }, [owner, name, branch, path, repoState.status]);

  if (repoState.status === 'loading') {
    return (
      <div className="page-shell">
        <p className="text-muted">Loading…</p>
      </div>
    );
  }
  if (repoState.status === 'missing') return <RepositoryMissing owner={owner} name={name} />;

  const repository = repoState.repository;
  const breadcrumbs = path ? path.split('/') : [];

  return (
    <div className="page-shell">
      <RepoHeader repository={repository} />
      <RepoNav
        owner={repository.owner}
        name={repository.name}
        active="code"
        showSettings={repository.viewerPermission.repository !== null}
      />

      <p className="mt-3 flex flex-wrap items-center gap-1 text-sm">
        <span className="inline-flex items-center gap-1 rounded-md border border-solid border-border bg-subtle px-2 py-0.5 font-600">
          <GitBranch size={12} aria-hidden="true" />
          {branch}
        </span>
        <Link className="text-accent" to={`/${repository.owner}/${repository.name}`}>
          {repository.name}
        </Link>
        {breadcrumbs.map((segment, index) => {
          const target = breadcrumbs.slice(0, index + 1).join('/');
          const isLast = index === breadcrumbs.length - 1;
          const url = `/${repository.owner}/${repository.name}/tree/${encodeURIComponent(branch)}/${target
            .split('/')
            .map(encodeURIComponent)
            .join('/')}`;
          return (
            <span key={target} className="inline-flex items-center gap-1">
              <span className="text-muted">/</span>
              {isLast && kind === 'file' ? (
                <span className="font-600">{segment}</span>
              ) : (
                <Link className="text-accent" to={url}>
                  {segment}
                </Link>
              )}
            </span>
          );
        })}
      </p>

      {state.status === 'loading' ? <p className="text-muted">Loading…</p> : null}
      {state.status === 'missing' ? <p className="text-muted">{repoCopy.pathNotFound}</p> : null}

      {state.status === 'ready' && state.contents.type === 'file' ? (
        <div className="app-card mt-3 overflow-hidden">
          {state.contents.commit ? (
            <p className="m-0 flex flex-wrap items-center gap-2 border-0 border-b border-solid border-border bg-subtle px-3 py-2 text-xs text-muted">
              <span className="font-600 text-fg">{state.contents.commit.author}</span>
              <span>{state.contents.commit.message}</span>
            </p>
          ) : null}
          <pre className="m-0 overflow-auto p-3 text-xs">
            <code>{state.contents.content}</code>
          </pre>
        </div>
      ) : null}

      {state.status === 'ready' && state.contents.type === 'directory' ? (
        <ul className="app-card mt-3 list-none divide-y divide-solid divide-border p-0">
          {state.contents.entries.map((entry) => (
            <li key={entry.path} className="flex items-center gap-2 px-3 py-2 text-sm">
              {entry.type === 'directory' ? (
                <Folder size={14} aria-hidden="true" className="text-muted" />
              ) : (
                <FileText size={14} aria-hidden="true" className="text-muted" />
              )}
              <Link className="text-accent" to={entry.url}>
                {entry.name}
              </Link>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

export default RepositoryContentsPage;

